// a shader variable
let theShader;

function preload(){
  // load the shader
  theShader = loadShader('https://openprocessing.org/sketch/1945864/files/shader.vert', 'shader.frag');
}

function setup() {
  // shaders require WEBGL mode to work
  createCanvas(1112, 834, WEBGL);
  noStroke();
	window.simulatedMouseX = width/2;
}

function draw() {  
  // shader() sets the active shader with our shader
  shader(theShader);

  theShader.setUniform("iResolution", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))*4, height*4]);                   // ***** CHANGED ******
  theShader.setUniform("iFrame", frameCount);
  theShader.setUniform("iMouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]); // ***** CHANGED ******

  // rect gives us some geometry on the screen
  rect(0,0,width, height);
}

function windowResized(){
  resizeCanvas(width, height);
}

